const all = $input.all().map(i => i.json);
const temas_raw    = all.filter(i => 'id' in i && 'tema' in i && 'score' in i);
const metricas_raw = all.filter(i => 'post_id' in i && 'likes' in i);
const rechazos_raw = all.filter(i => 'motivo' in i && !('score' in i));
const temasMap = {};
for (const t of temas_raw) {
  const id = (t.id || '').trim();
  if (!id) continue;
  if (!temasMap[id] || (t.row_number || 999) < (temasMap[id].row_number || 999)) temasMap[id] = t;
}
return [{ json: { temas: Object.values(temasMap), metricas: metricas_raw, rechazos: rechazos_raw } }];

const { temas, metricas, rechazos } = $('Parsear Sheets').first().json;
const ahora = Date.now();
const candidatos = temas.filter(t => {
  const e = (t.estado || '').toLowerCase().trim();
  // Excluir solo los que explícitamente NO deben publicarse
  if (e === 'rechazado' || e === 'pausado' || e === 'eliminado' || e === 'inactivo') return false;
  // Publicados recientemente: esperar 21 días
  if (e === 'publicado' && t.fecha_pub) return (ahora - new Date(t.fecha_pub).getTime()) > 21*86400000;
  // Todo lo demás es candidato (pendiente, disponible, aprobado, vacío, etc.)
  return true;
});
if (!candidatos.length) {
  const estados = [...new Set(temas.map(t => t.estado || '(vacío)'))].join(', ');
  throw new Error(`Sin temas disponibles. Estados encontrados: ${estados}`);
}

const erPorArea = {};
metricas.forEach(m => { const a = m.area||m.tema||''; const er = parseFloat(m.engagement_rate)||0; if (!erPorArea[a]) erPorArea[a]=[]; erPorArea[a].push(er); });
const todosER = metricas.map(m => parseFloat(m.engagement_rate)||0).filter(e=>e>0).sort((a,b)=>a-b);
const p25 = todosER[Math.floor(todosER.length*.25)]||0.0097;
const p75 = todosER[Math.floor(todosER.length*.75)]||0.0181;
const hace14 = ahora - 14*86400000;
const rechRec = {};
rechazos.forEach(r => { const f = new Date(r.fecha||0).getTime(); if(f>hace14) rechRec[r.tema_id]=(rechRec[r.tema_id]||0)+1; });

const dw = new Date().getDay();
const tonosDia = {1:'reflexivo',3:'herramienta',5:'provocador'};
const tonoCtx = tonosDia[dw]||'directo';
const dias = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];

candidatos.forEach(t => {
  let s = parseFloat(t.score||1);
  s *= (1 - Math.min(parseInt(t.veces_publicado||0)*.20, .60));
  if (t.fecha_pub) { const d=(ahora-new Date(t.fecha_pub).getTime())/86400000; s*=(1+Math.min((d/7)*.05,.40)); } else s*=1.5;
  const erA = erPorArea[t.area||'']||[];
  if (erA.length) { const avg=erA.reduce((a,b)=>a+b,0)/erA.length; if(avg>p75)s*=1.3; else if(avg<p25)s*=0.8; }
  s *= Math.pow(.75, rechRec[t.id]||0);
  if ((t.tono||'').toLowerCase()===tonoCtx) s*=1.05;
  s *= (.85+Math.random()*.45);
  if (t.fecha_propuesto) { const dp=(ahora-new Date(t.fecha_propuesto).getTime())/86400000; if(dp<7)s*=.4; }
  t.score_final = Math.round(s*100)/100;
});

const top3 = candidatos.sort((a,b)=>b.score_final-a.score_final).slice(0,3);
const total = top3.reduce((a,t)=>a+t.score_final,0);
let r = Math.random()*total, ganador = top3[0];
for (const t of top3) { r -= t.score_final; if (r<=0) { ganador=t; break; } }
const erProm = todosER.length ? todosER.reduce((a,b)=>a+b,0)/todosER.length : 0.0139;

return [{ json: {
  ...ganador,
  tema: ganador.tema_nombre || ganador.tema,
  tipo_post: ganador.tipo_post||'reflexión',
  nivel_profundidad: ganador.nivel_profundidad||'avanzado',
  tono: ganador.tono||tonoCtx,
  objetivo: ganador.objetivo||'posicionamiento',
  contexto_dia: `${dias[dw]} — tono recomendado: ${tonoCtx}`,
  tone_hint: `ER promedio histórico: ${(erProm*100).toFixed(2)}%`,
  er_promedio: erProm
}}];

const tema = $('Calcular Prioridad').first().json;
const sp   = $('System Prompt').first().json.system_prompt;
return [{ json: { ...tema, system_prompt: sp } }];

const raw = $json.message?.content || $json.choices?.[0]?.message?.content || '';
if (!raw) throw new Error('Agente Analista vacío');
let s = raw.trim().replace(/```json\s*/gi,'').replace(/```/g,'').trim();
const tm = s.match(/<\/think>\s*([\s\S]*)/); if (tm) s = tm[1].trim();
let o;
try { o = JSON.parse(s); } catch(e) { const m=s.match(/\{[\s\S]*\}/); if(!m) throw new Error('Sin JSON en Analista: '+s.substring(0,200)); o=JSON.parse(m[0]); }
const pts = (o.puntos_desarrollo||[]).join('\n→ ');
const proh = (o.palabras_prohibidas_contexto||[]).join(', ');
const inj = `El post debe explorar: ${o.tension||''}\nTu postura en este post: ${o.postura_central||''}\nEmpieza con algo como esto (no lo copies exacto, adáptalo a tu voz): "${o.gancho||''}"\nDesarrolla estos ángulos en párrafos corridos, NO como lista:\n${(o.puntos_desarrollo||[]).map(p=>'— '+p).join('\n')}\n${o.ejemplo_concreto ? 'Ejemplo o anécdota concreta si tienes una: '+o.ejemplo_concreto : ''}\n${proh ? 'Palabras a evitar en este post: '+proh : ''}`;
return [{ json: { ...$('Combinar Contexto').first().json, outline: o, outline_injection: inj } }];

const raw = $json.message?.content || $json.choices?.[0]?.message?.content || '';
if (!raw) throw new Error('Agente Escritor vacío');
let s = raw.trim().replace(/```json\s*/gi,'').replace(/```/g,'').trim();
const tm = s.match(/<\/think>\s*([\s\S]*)/); if (tm) s = tm[1].trim();
let d;
try { d = JSON.parse(s); } catch(e) {
  const m = s.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Sin JSON en Escritor: '+s.substring(0,200));
  let t = m[0];
  const op=(t.match(/\{/g)||[]).length, cl=(t.match(/\}/g)||[]).length;
  for(let i=0;i<op-cl;i++) t+='}';
  d = JSON.parse(t);
}
if (!d.post_text || d.post_text.length < 200) throw new Error('post_text muy corto: '+(d.post_text||'').length);
const prev = $('Parsear Outline').first().json;
return [{ json: { ...prev, draft: d, draft_json_str: JSON.stringify(d) } }];

// Lee el historial ya cargado desde Parsear Sheets (dentro del mismo workflow)
const parsed = $('Parsear Sheets').first().json;
const temas    = parsed.temas    || [];
const metricas = parsed.metricas || [];

// Build ER map: post_id → max ER
const erMap = {};
metricas.forEach(m => {
  const er = parseFloat(m.engagement_rate) || 0;
  if (!erMap[m.post_id] || er > erMap[m.post_id]) erMap[m.post_id] = er;
});

// Find published temas that have post_text stored and an ER record
const con_texto = temas
  .filter(t => t.estado === 'publicado' && t.post_text && t.post_id && erMap[t.post_id])
  .map(t => ({ ...t, best_er: erMap[t.post_id] }))
  .sort((a, b) => b.best_er - a.best_er)
  .slice(0, 2);

let ejemplos_str = '';
if (con_texto.length > 0) {
  ejemplos_str = '\n\nEJEMPLOS REALES DE POSTS DE CAMILO CON ALTO ENGAGEMENT:\n';
  ejemplos_str += '(Usa estos como referencia del TONO y RITMO — no copies frases)\n';
  con_texto.forEach((p, i) => {
    const er_pct = (p.best_er * 100).toFixed(2);
    ejemplos_str += `\n[EJEMPLO ${i + 1} — ER real: ${er_pct}%]\n`;
    ejemplos_str += p.post_text.trim();
    ejemplos_str += `\n[FIN EJEMPLO ${i + 1}]\n`;
  });
}

// Pass through everything from Parsear Draft, just adding the examples
const prev = $('Parsear Draft').first().json;
return [{ json: { ...prev, ejemplos_humanizador: ejemplos_str } }];

const raw = $json.message?.content || $json.choices?.[0]?.message?.content || '';
let s = (raw||'').trim().replace(/```json\s*/gi,'').replace(/```/g,'').trim();
const tm = s.match(/<\/think>\s*([\s\S]*)/); if (tm) s = tm[1].trim();
let fp;
try { fp = JSON.parse(s); } catch(e) { fp = $('Parsear Draft').first().json.draft || {}; }
let pt = (fp.post_text||'').trim().replace(/\r\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();
if (!pt || pt.length < 200) pt = $('Parsear Draft').first().json.draft?.post_text || '';
const base = $('Parsear Outline').first().json;
return [{ json: {
  ...base,
  post_text: pt,
  hook_type: fp.hook_type || 'directo',
  imagen_descripcion: fp.imagen_descripcion || base.imagen_descripcion || 'creative professional workspace',
  hashtags: fp.hashtags || base.hashtags || ['#diseño','#comunicación','#educación','#Colombia'],
  caracteres: pt.length,
  parrafos: pt.split('\n\n').filter(p=>p.trim()).length
}}];

const data = $json;
const texto = data.post_text || '';
let score = 100;
const problemas = [];
if (texto.length > 2700) { score -= 20; problemas.push('Largo: '+texto.length); }
else if (texto.length < 500) { score -= 35; problemas.push('Corto: '+texto.length); }
['en el mundo actual','es fundamental','la clave está en','es importante','cada vez más',
 'sin lugar a dudas','definitivamente','en definitiva','no es casualidad','más allá de',
 'lo que muchos no saben','esto nos lleva','cabe mencionar','vale la pena destacar',
 'sinergia','disruptivo','transformacional','paradigma','ecosistema','empoderamiento'
].forEach(f => { if (texto.toLowerCase().includes(f)) { score-=8; problemas.push(`IA:"${f}"`); } });
if (/\p{Emoji_Presentation}/u.test(texto)) { score-=25; problemas.push('Emojis'); }
const excl = (texto.match(/!/g)||[]).length;
if (excl>0) { score-=excl*15; problemas.push(`${excl} exclamaciones`); }
if (texto.split('\n\n').filter(p=>p.trim()).length < 3) { score-=15; problemas.push('Pocos párrafos'); }
if (/^(tema|tono|tipo|área|profundidad):/im.test(texto)) { score-=30; problemas.push('Metadata en texto'); }
if (texto.trim().startsWith('#')) { score-=20; problemas.push('Empieza con #'); }
score = Math.max(0, score);
return [{ json: { ...data, calidad_score: score, calidad_pasa: score >= 55, calidad_problemas: problemas,
  calidad_label: score>=80?'🟢 Bueno':score>=55?'🟡 Aceptable':'🔴 Bajo' } }];

const d = $json;

// Unsplash is English-indexed → build query 100% in English.
// We use /search/photos (ranked by relevance) instead of /photos/random
// so the MOST relevant photo is always result[0], not a random tangential one.

const areaMap = {
  'diseño': 'design studio workspace creative professional',
  'educación': 'education learning classroom students training',
  'marketing': 'marketing business meeting team strategy',
  'tecnología': 'technology software developer computer code',
  'liderazgo': 'leadership manager business team office',
  'emprendimiento': 'entrepreneur startup coworking business founders',
  'innovación': 'innovation ideas brainstorming office team',
  'comunicación': 'communication meeting people talking presentation',
  'branding': 'brand identity logo design creative agency',
  'negocios': 'business office professional meeting corporate',
  'cultura': 'workplace culture diversity team collaboration',
  'productividad': 'productivity focus work desk professional',
  'estrategia': 'strategy planning business whiteboard team',
  'finanzas': 'finance business professional analyst office',
  'recursos humanos': 'human resources people management hiring team',
  'ventas': 'sales business handshake deal meeting',
};

const areaRaw = (d.area || '').toLowerCase();
let anchor = 'business professional people team office'; // safe default
for (const [key, val] of Object.entries(areaMap)) {
  if (areaRaw.includes(key)) { anchor = val; break; }
}

// Use only the anchor — keep query short and precise so Unsplash ranks well.
// Do NOT include Spanish text (imagen_descripcion, post_text) which confuses
// the English-indexed search engine and causes irrelevant results.
const query = encodeURIComponent(anchor);

return [{ json: {
  ...d,
  unsplash_url: 'https://api.unsplash.com/search/photos?query=' + query +
                '&per_page=3&content_filter=high&client_id=zH4HKmqhf9FTlBggBT9cntXXEzZXGnHN0Oc59zP7wLI'
} }];

const prev = $('Seleccionar Imagen').first().json;
const resp = $json;

let img_url = '';
let img_credit = '';

// /search/photos returns { results: [...], total, total_pages }
// Pick randomly among the top results to avoid always the same photo
if (resp.results && resp.results.length > 0) {
  const pick = resp.results[Math.floor(Math.random() * resp.results.length)];
  img_url = pick.urls?.regular || pick.urls?.full || pick.urls?.small || '';
  if (img_url) {
    const name = pick.user?.name || pick.user?.username || 'Unsplash';
    const username = pick.user?.username ? '@' + pick.user.username : '';
    img_credit = '📷  ' + name + (username ? ' [' + username + ']' : '') + ', Unsplash';
  }
}

if (!img_url || img_url.length < 10) {
  const seed = (prev.id || 'content') + Date.now().toString(36);
  img_url = 'https://picsum.photos/seed/' + seed + '/1200/628';
  img_credit = 'Foto de Unsplash';
}

return [{ json: {
  ...prev,
  imagen_url: img_url,
  imagen_credit: img_credit
} }];

const d = $json;
const txt = (d.post_text||'');
const hashtags = Array.isArray(d.hashtags) ? d.hashtags.join(' ') : (d.hashtags||'');
const score = d.calidad_score||0;
const label = d.calidad_label||'';
const chars = d.caracteres || txt.length;

function esc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

// Cabecera: ~80 chars. Post preview: rellena el resto hasta 1020 chars.
const header = `📝 <b>${esc((d.tema||'').substring(0,75))}</b>\nCalidad: ${score}/100 ${label} · ${chars} chars\n`;
const credit = d.imagen_credit ? '\n' + esc(d.imagen_credit) : '';
const footer = '\n' + hashtags + credit;
const maxPost = 1020 - header.length - footer.length;
const postPreview = esc(txt.length > maxPost ? txt.substring(0, maxPost-3)+'...' : txt);

const caption = header + postPreview + footer;

const keyboard = {
  inline_keyboard: [
    [
      { text: '✅ Publicar', callback_data: `v2|aprobar|${d.id}` },
      { text: '📝 Solo texto', callback_data: `v2|solo_texto|${d.id}` }
    ],
    [
      { text: '🔄 Regenerar', callback_data: `v2|regenerar|${d.id}` },
      { text: '❌ Rechazar', callback_data: `v2|rechazar|${d.id}` }
    ]
  ]
};

const tg_keyboard_str = JSON.stringify(keyboard);
return [{ json: { ...d, tg_caption: caption, tg_keyboard: keyboard, tg_keyboard_str } }];

